alter table public.data_feature_events add column if not exists event_validity text not null default 'valid'; alter table public.data_feature_events add column if not exists confidence numeric not null default 1; alter table public.data_feature_events add column if not exists deduplication_key text; alter table public.data_feature_events add column if not exists rate_limit_context jsonb not null default '{}'::jsonb; alter table public.data_feature_events add constraint data_feature_events_validity_check check(event_validity in ('valid','duplicate','abusive','untrusted','invalid')) not valid; alter table public.data_feature_events add constraint data_feature_events_confidence_check check(confidence>=0 and confidence<=1) not valid; create index if not exists idx_data_feature_events_dedup on public.data_feature_events(deduplication_key) where deduplication_key is not null; create or replace function public.record_data_feature_event(p_event_type text,p_feature_code text default null,p_subject_type text default 'user',p_subject_id uuid default null,p_location_id uuid default null,p_business_id uuid default null,p_fleet_vehicle_id uuid default null,p_source_table text default null,p_source_id uuid default null,p_value_numeric numeric default null,p_value_text text default null,p_metadata jsonb default '{}'::jsonb) returns public.data_feature_events language plpgsql security definer set search_path to 'public' as $function$ declare uid uuid:=auth.uid(); r public.data_feature_events; v_key text; begin if uid is null then raise exception 'Authentication required'; end if; v_key:=md5(concat_ws('|',uid::text,p_event_type,coalesce(p_source_id::text,''),coalesce(p_location_id::text,''),coalesce(p_value_text,''),date_trunc('minute',now())::text)); insert into public.data_feature_events(subject_type,subject_id,actor_user_id,business_id,location_id,fleet_vehicle_id,event_type,feature_code,source_table,source_id,value_numeric,value_text,metadata,occurred_at,event_validity,confidence,deduplication_key,rate_limit_context) values(p_subject_type,coalesce(p_subject_id,uid),uid,p_business_id,p_location_id,p_fleet_vehicle_id,p_event_type,p_feature_code,p_source_table,p_source_id,p_value_numeric,p_value_text,coalesce(p_metadata,'{}'::jsonb),now(),'valid',1,v_key,jsonb_build_object('minute',date_trunc('minute',now()))) returning * into r; return r; end $function$;
